    # standard Bateman 1-compartment oral model, F=1, C = D*ka/(V(ka-ke))*(exp(-ke t)-exp(-ka t))
    return D*ka/(V*(ka-ke))*(np.exp(-ke*t)-np.exp(-ka*t))

